def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "deliver_reminder_close": And([
            self.robot_at(self.resident_location),  # Robot is close to resident
            self.resident_is_present,  # Resident is present
            Not(self.at_distant_position)  # Not maintaining distance
        ]),  # Delivering reminder too close invades personal space
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
